// I: farthest reach
int far = 0;
for (int i = 0; i < n; i++) {
    if (i > far) return false;
    far = max(far, i + a[i]);
}
// II: BFS-layers in place
int jumps = 0, curEnd = 0, far = 0;
for (int i = 0; i < n - 1; i++) {
    far = max(far, i + a[i]);
    if (i == curEnd) { jumps++; curEnd = far; }
}

// sort arrivals & departures; two pointers
int plat = 0, best = 0, i = 0, j = 0;
while (i < n) {
    if (arr[i] <= dep[j]) { plat++; i++; }   // tie: arrive first!
    else { plat--; j++; }
    best = max(best, plat);
}
